namespace Censio.GameData.Tests;

/// <summary>
/// Tests for <see cref="Bc7Decoder" />. The expected pixels were produced once outside the repository by
/// BCnEncoder.NET 2.3.0 (MIT or Unlicense) on randomly filled blocks written field by field in the layouts of the
/// BC7 format description, and equal a second, independent decoder worked from the description on 57,000 such blocks;
/// the partition tables of both agree with the tables of Microsoft's DirectXTex. The first value of each row is
/// the block, the second the 16 RGBA pixels, both as hexadecimal text.
/// </summary>
[TestClass]
public sealed class Bc7DecoderTests
{
    #region Constants

    /// <summary>
    /// The size of the decoded pixels of one block in bytes.
    /// </summary>
    private const int PixelBytes = 64;

    #endregion // Constants

    #region Methods

    /// <summary>
    /// A block of each mode 0 to 7 decodes to the pixels of the reference decoder.
    /// </summary>
    /// <param name="blockHex">The block as hexadecimal text</param>
    /// <param name="expectedHex">The expected 64 RGBA bytes as hexadecimal text</param>
