    public void Bc7DecoderDecodeBlockModeMatchesReference(string blockHex, string expectedHex)
    {
        // Arrange
        var block = Convert.FromHexString(blockHex);
        var rgba = new byte[PixelBytes];

        Array.Fill(rgba, (byte)0xFF);

        // Act
        Bc7Decoder.DecodeBlock(block, rgba);

        // Assert
        Assert.AreEqual(expectedHex, Convert.ToHexString(rgba), "The pixels should equal the reference decoder's");
    }

